"""统一传统 RAG：BM25 / 向量 / RRF / 强制本地 CrossEncoder 精排。"""

import os
import sys
import json
import argparse

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import kb_lib as K

SCHEMA_VERSION = "kb.rag.v1"
DEFAULT_RERANKER = "BAAI/bge-reranker-base"
_RERANKERS = {}


class RetrievalUnavailable(RuntimeError):
    pass


def reranker_name(model=None):
    return model or os.environ.get("MATSCI_RERANKER_MODEL", DEFAULT_RERANKER)


def load_reranker(model=None, allow_download=False):
    name = reranker_name(model)
    # 环境变量授权对 doctor 等所有入口生效（旧实现只在 retrieve 里转换）
    allow_download = _allow_download(allow_download)
    key = (name, bool(allow_download))
    if key in _RERANKERS:
        return _RERANKERS[key]
    try:
        from sentence_transformers import CrossEncoder
    except ImportError as exc:
        raise RetrievalUnavailable(
            "缺少 sentence-transformers，无法执行强制精排；请安装后重试") from exc
    try:
        instance = CrossEncoder(name, local_files_only=not allow_download)
    except Exception as exc:
        action = ("确认 MATSCI_RERANKER_MODEL 指向已下载的本地模型；"
                  "首次下载可显式设置 MATSCI_RERANKER_ALLOW_DOWNLOAD=1")
        raise RetrievalUnavailable(f"本地 Reranker {name!r} 不可用：{exc}；{action}") from exc
    _RERANKERS[key] = instance
    return instance


def _allow_download(flag=False):
    return flag or os.environ.get("MATSCI_RERANKER_ALLOW_DOWNLOAD", "") == "1"


def _check_semantic(SEM):
    embeddings, embed_map = SEM._load_embeddings()
    if embeddings is None:
        raise RetrievalUnavailable("嵌入索引不存在；请先运行 kb.py index embed")
    missing, stale, fresh = SEM.check_index_freshness(embed_map, verbose=False)
    if not fresh:
        raise RetrievalUnavailable(
            f"嵌入索引过期（缺失 {len(missing)}，幽灵 {len(stale)}）；请先运行 kb.py index embed")


def _candidate_text(path, summary, max_chars):
    text = summary or ""
    if path:
        full = os.path.join(K.VAULT, *path.split("/"))
        if os.path.isfile(full):
            _fm, body = K.split_frontmatter(K.read_text(full))
            text = (text + "\n" + body).strip()
    return text[:max_chars]


def _metadata(KS, meta, name):
    summary, updated, tags, aliases, ptype = KS.meta_of(meta, name)
    path = KS.page_path(name, ptype)
    return {
        "name": name,
        "type": ptype,
        "summary": summary,
        "updated": updated,
        "tags": tags,
        "aliases": aliases,
        "path": path,
        "locator": {"path": path} if path else None,
    }


def retrieve(query, k=10, mode="hybrid", type_filter=None, candidate_k=0,
             rerank_k=0, reranker_model=None, allow_download=False,
             rerank_max_chars=4000):
    if mode not in ("bm25", "semantic", "hybrid"):
        raise ValueError("mode 必须是 bm25 / semantic / hybrid")
    if not query.strip():
        raise ValueError("query 不能为空")
    k = max(1, int(k))
    candidate_k = max(k, int(candidate_k or max(20, k * 5)))
    types = set(type_filter or ())

    import kb_search as KS
    import kb_semantic_search as SEM
    meta, _bm = KS.load_index()
    if mode in ("semantic", "hybrid"):
        _check_semantic(SEM)

    bm = KS_bm25 = None
    sem = None
    if mode in ("bm25", "hybrid"):
        KS_bm25 = SEM._bm25_search(query, top_k=candidate_k)
        bm = KS_bm25
    if mode in ("semantic", "hybrid"):
        sem = SEM.semantic_search(query, top_k=candidate_k)

    warnings = []
    if mode == "hybrid" and not bm:
        warnings.append("bm25_empty: 本轮仅向量候选参与融合")
    if mode == "hybrid" and not sem:
        raise RetrievalUnavailable("向量召回为空；拒绝把 hybrid 静默降级为 BM25")

    fused = {}
    if mode == "bm25":
        for rank, (name, score) in enumerate(bm or [], 1):
            fused[name] = {"bm25": float(score), "rank_bm25": rank, "fusion": float(score)}
    elif mode == "semantic":
        for rank, (name, score) in enumerate(sem or [], 1):
            fused[name] = {"semantic": float(score), "rank_semantic": rank,
                           "fusion": float(score)}
    else:
        for rank, (name, score) in enumerate(bm or [], 1):
            row = fused.setdefault(name, {})
            row.update({"bm25": float(score), "rank_bm25": rank})
        for rank, (name, score) in enumerate(sem or [], 1):
            row = fused.setdefault(name, {})
            row.update({"semantic": float(score), "rank_semantic": rank})
        for name, row in fused.items():
            score = 0.0
            if row.get("rank_bm25"):
                score += 1.0 / (60 + row["rank_bm25"])
            if row.get("rank_semantic"):
                score += 1.0 / (60 + row["rank_semantic"])
            row["fusion"] = score

    rows = []
    for name, scores in fused.items():
        item = _metadata(KS, meta, name)
        if types and item["type"] not in types:
            continue
        item["scores"] = scores
        item["score"] = round(scores["fusion"], 6)
        rows.append(item)
    rows.sort(key=lambda x: (-x["scores"]["fusion"], x["name"]))

    ranking = {
        "candidate_k": candidate_k,
        "candidates_after_filter": len(rows),
        "fusion": "rrf" if mode == "hybrid" else "none",
        "reranker": {"required": False, "applied": False},
    }
    if mode == "hybrid":
        limit = max(k, int(rerank_k or max(10, k * 3)))
        rows = rows[:limit]
        model_name = reranker_name(reranker_model)
        ranker = load_reranker(model_name, allow_download=_allow_download(allow_download))
        pairs = [[query, _candidate_text(x["path"], x["summary"], rerank_max_chars)]
                 for x in rows]
        try:
            values = ranker.predict(pairs)
        except Exception as exc:
            raise RetrievalUnavailable(f"Reranker 推理失败：{exc}") from exc
        for item, value in zip(rows, values):
            item["scores"]["rerank"] = float(value)
            item["score"] = float(value)
        rows.sort(key=lambda x: (-x["scores"]["rerank"], x["name"]))
        ranking["reranker"] = {
            "required": True,
            "applied": True,
            "model": model_name,
            "candidate_k": len(rows),
            "local_files_only": not _allow_download(allow_download),
        }
    else:
        rows = rows[:k]

    results = rows[:k]
    for rank, item in enumerate(results, 1):
        item["rank"] = rank
    return {
        "schema_version": SCHEMA_VERSION,
        "ok": True,
        "strategy": "traditional",
        "mode": mode,
        "query": query,
        "count": len(results),
        "results": results,
        "ranking": ranking,
        "warnings": warnings,
    }


def selftest():
    ok = fail = 0

    def chk(label, condition):
        nonlocal ok, fail
        ok += bool(condition)
        fail += not bool(condition)
        print(f"  [{'ok' if condition else 'FAIL'}] {label}")

    # 自检必须与环境无关：先摘掉外部注入的两个变量，再测「默认值」
    old = dict(os.environ)
    os.environ.pop("MATSCI_RERANKER_MODEL", None)
    os.environ.pop("MATSCI_RERANKER_ALLOW_DOWNLOAD", None)
    try:
        chk("默认精排模型明确", reranker_name({}.get("x")) == DEFAULT_RERANKER)
        chk("环境变量可指定本地精排模型", callable(load_reranker))
        os.environ["MATSCI_RERANKER_MODEL"] = "local-test-model"
        chk("模型配置覆盖", reranker_name() == "local-test-model")
        os.environ["MATSCI_RERANKER_ALLOW_DOWNLOAD"] = "1"
        chk("下载必须显式开启", _allow_download(False) is True)
    finally:
        os.environ.clear()
        os.environ.update(old)
    print(f"SELFTEST {'PASSED' if not fail else 'FAILED'}: {ok}/{ok + fail}")
    return 0 if not fail else 1


def main():
    ap = argparse.ArgumentParser(description="统一传统 RAG")
    ap.add_argument("query", nargs="?", default="")
    ap.add_argument("--mode", choices=["bm25", "semantic", "hybrid"], default="hybrid")
    ap.add_argument("-k", type=int, default=10)
    ap.add_argument("--type", default="")
    ap.add_argument("--candidate-k", type=int, default=0)
    ap.add_argument("--rerank-k", type=int, default=0)
    ap.add_argument("--reranker-model", default="")
    ap.add_argument("--allow-download", action="store_true")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()
    if args.selftest:
        return selftest()
    if not args.query:
        ap.error("query 不能为空（--selftest 除外）")
    try:
        data = retrieve(args.query, k=args.k, mode=args.mode,
                        type_filter=[x for x in args.type.split(",") if x],
                        candidate_k=args.candidate_k, rerank_k=args.rerank_k,
                        reranker_model=args.reranker_model or None,
                        allow_download=args.allow_download)
    except (ValueError, RetrievalUnavailable) as exc:
        data = {"schema_version": SCHEMA_VERSION, "ok": False,
                "error": {"type": type(exc).__name__, "message": str(exc)}}
        print(K.json_dumps(data, ensure_ascii=False, indent=1))
        return 3 if isinstance(exc, RetrievalUnavailable) else 2
    if args.json:
        print(K.json_dumps(data, ensure_ascii=False, indent=1))
    else:
        print(f"[{data['mode']}] {args.query}：{data['count']} 条")
        for item in data["results"]:
            print(f"{item['rank']:>2}. [{item['type']}] {item['name']}  {item['score']:.4f}")
            print(f"    {item['path']}")
    return 0


if __name__ == "__main__":
    K.console_encoding()
    sys.exit(main())
